  public static func ==(lhs: Kiapi_Common_Project_TextVariables, rhs: Kiapi_Common_Project_TextVariables) -> Bool {
    if lhs.variables != rhs.variables {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
